package jp.tapmarker;
public class VirtualTargetTest {
 public static void main(String[] args){int checks=0;for(int display=1;display<=4;display++){float[] center=VirtualTarget.map(display,720,1600,.5f,.5f);if(center[0]!=360||center[1]!=800)throw new AssertionError("display-local center");checks++;float[] edge=VirtualTarget.map(display,720,1600,1,1);if(edge[0]!=719||edge[1]!=1599)throw new AssertionError("inside bounds");checks++;}for(int id:new int[]{0,-1}){boolean caught=false;try{VirtualTarget.map(id,720,1600,.5f,.5f);}catch(IllegalArgumentException e){caught=true;}if(!caught)throw new AssertionError("physical display rejected");checks++;}for(float x:new float[]{-1,2,Float.NaN,Float.POSITIVE_INFINITY}){boolean caught=false;try{VirtualTarget.map(3,720,1600,x,.5f);}catch(IllegalArgumentException e){caught=true;}if(!caught)throw new AssertionError("invalid point rejected");checks++;}System.out.println("VirtualTargetTest: "+checks+" checks passed; device input not tested");}
}
